package com.himeros.trustsafety;import com.himeros.shared.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/safety")public class TrustSafetyController{private final TrustSafetyService service;private final CurrentUser current;public TrustSafetyController(TrustSafetyService s,CurrentUser c){service=s;current=c;}@PostMapping("/blocks/{target}")@ResponseStatus(HttpStatus.NO_CONTENT)void block(@PathVariable UUID target){service.block(current.id(),target);}@DeleteMapping("/blocks/{target}")@ResponseStatus(HttpStatus.NO_CONTENT)void unblock(@PathVariable UUID target){service.unblock(current.id(),target);}@PostMapping("/reports/{target}")@ResponseStatus(HttpStatus.CREATED)Map<String,UUID> report(@PathVariable UUID target,@Valid@RequestBody ReportRequest r){return Map.of("reportId",service.report(current.id(),target,r.reason(),r.details()));}public record ReportRequest(@NotBlank@Size(max=80)String reason,@Size(max=1000)String details){}}
